CREATE FUNCTION mask_ssn(ssn STRING)
RETURN CASE WHEN is_member('pii-readers') THEN ssn
            ELSE 'XXX-XX-' || RIGHT(ssn, 4) END;

ALTER TABLE nyc_taxi.silver.customers ALTER COLUMN ssn SET MASK mask_ssn;
ALTER TABLE nyc_taxi.silver.support_tickets
  ALTER COLUMN customer_ssn SET MASK mask_ssn;
